1094	// extractRemotePath strips the server from a git remote URL and returns only the path.
1095	// Examples:
1096	//
1097	//	"https://gitlab.com/group/project.git" → "group/project"
1098	//	"git@gitlab.com:group/project.git"     → "group/project"
1099	func extractRemotePath(rawURL string) string {
1100		// SCP-like syntax: git@host:path — colon must not be followed by "//"
1101		if idx := strings.Index(rawURL, ":"); idx != -1 && !strings.Contains(rawURL[:idx], "/") {
1102			after := rawURL[idx+1:]
1103			if !strings.HasPrefix(after, "//") {
1104				return strings.TrimSuffix(after, ".git")
1105			}
1106		}
1107		// URL syntax: scheme://host/path
1108		if idx := strings.Index(rawURL, "://"); idx != -1 {
1109			rest := rawURL[idx+3:]
1110			if slash := strings.Index(rest, "/"); slash != -1 {
1111				return strings.TrimSuffix(rest[slash+1:], ".git")
1112			}
1113		}
1114		return rawURL
1115	}
