1113	// expandToPath navigates to and selects a node at the given path after refresh
1114	func (m Model) expandToPath(targetPath string) (tea.Model, tea.Cmd) {
1115		// Check if the target is visible in current items
1116		items := m.currentItems()
1117		for i, node := range items {

1117		for i, node := range items {
1118			if node.FullPath == targetPath {
1119				m.table.SetCursor(i)
1120				m.pendingSelectPath = ""
1121				return m, nil
1122			}
1123		}
1124	
1125		// Find an ancestor that needs to be drilled into
1126		for _, node := range items {
1127			if node.Type == NodeTypeGroup && strings.HasPrefix(targetPath, node.FullPath+"/") {
1128				// Drill into this group
1129				m.navigationStack = append(m.navigationStack, m.currentGroupNode)
1130				m.currentGroupNode = node
1131	
1132				if node.Children == nil {
1133					node.Loading = true
1134					m.updateTableRows()
1135					return m, m.loadChildren(node)
1136				}
1137				node.Expanded = true
1138				m.updateTableRows()
1139				return m.expandToPath(targetPath)
1140			}
1141		}
1142	
1143		// Could not find path - clear pending and stay where we are
1144		m.pendingSelectPath = ""
1145		return m, nil
1146	}
