1213	// handleDeleteComplete handles DeleteCompleteMsg
1214	func (m Model) handleDeleteComplete(msg DeleteCompleteMsg) (tea.Model, tea.Cmd) {
1215		if msg.Error != nil {
1216			log.Printf("ERROR [explorer] delete: %v", msg.Error)
1217			m.footerError = "Delete failed — check logs"
1218			return m, nil
1219		}
1220		m.footerError = ""
1221	
1222		// Remove deleted node from local tree and stay in current group
1223		if msg.DeletedNode != nil {
1224			if m.currentGroupNode != nil {
1225				children := m.currentGroupNode.Children
1226				for i, child := range children {
1227					if child.ID == msg.DeletedNode.ID {
1228						m.currentGroupNode.Children = append(children[:i], children[i+1:]...)
1229						break
1230					}
1231				}
1232			} else {
1233				for i, n := range m.nodes {
1234					if n.ID == msg.DeletedNode.ID {
1235						m.nodes = append(m.nodes[:i], m.nodes[i+1:]...)
1236						break
1237					}
1238				}
1239			}
1240		}
1241		m.updateTableRows()
1242		return m, nil
1243	}
