// Stages are kept in arrival order and updated in place, so a stage that
// reports twice does not appear twice.
func TestProgressUpdatesStagesInPlace(t *testing.T) {
	m := newTestModel(t)

	m = feed(t, m,
		ScanProgressMsg{Update: scan.ProgressUpdate{Stage: "trivy vuln", Message: "starting"}},
		ScanProgressMsg{Update: scan.ProgressUpdate{Stage: "gitleaks", Message: "starting"}},
		ScanProgressMsg{Update: scan.ProgressUpdate{Stage: "trivy vuln", Message: "done"}},
	)

	if len(m.scanStages) != 2 {
		t.Fatalf("scanStages = %+v, want one entry per stage", m.scanStages)
	}
