31	// parseScanError splits a scan error string into a source label (e.g. "trivy vuln") and
32	// a cleaned detail message with only FATAL/ERROR/WARN lines from tool stderr.
33	func parseScanError(errMsg string) (source, detail string) {
34		// Format: "source: tool failed: <stderr>"
35		idx := strings.Index(errMsg, ": ")
36		if idx == -1 {
37			return "", extractMeaningfulLines(errMsg)
38		}
39		source = errMsg[:idx]
40		rest := errMsg[idx+2:]
41	
42		// Strip the intermediate "tool failed: " prefix
43		for _, prefix := range []string{
44			"trivy failed: ",
45			"trivy misconfig failed: ",
46			"sbom generation failed: ",
47			"gitleaks failed: ",
48		} {
49			if strings.HasPrefix(rest, prefix) {
50				rest = rest[len(prefix):]
51				break
52			}
53		}
54	
55		return source, extractMeaningfulLines(rest)
56	}
57	
58	// extractMeaningfulLines filters tool stderr output, keeping only FATAL/ERROR/WARN lines
59	// and discarding INFO log lines and progress bar output.
60	// Handles both tab (\t) and multi-space separators (zerolog vs logrus formats).
61	func extractMeaningfulLines(text string) string {
62		var kept []string
63		for _, line := range strings.Split(text, "\n") {
64			line = strings.TrimRight(line, "\r")
65			if strings.TrimSpace(line) == "" {
66				continue
67			}
68			// Skip progress bar lines (download indicators from trivy-db)
69			if strings.Contains(line, " MiB /") || strings.Contains(line, " p/s ") || strings.Contains(line, "[---") {
70				continue
71			}
72			// Detect timestamped log line: starts with YYYY-MM-DD
73			if len(line) > 10 && line[4] == '-' && line[7] == '-' {
74				level, message := splitLogLine(line)
75				switch strings.ToUpper(level) {
76				case "INFO":
77					continue // discard
78				case "FATAL", "ERROR", "WARN", "WARNING":
79					kept = append(kept, formatScanErrorLine(level, message))
80					continue
81				}
82			}
83			// Non-structured line (plain error text) — keep as-is
84			kept = append(kept, line)
85		}
86		if len(kept) == 0 {
87			return strings.TrimSpace(text) // fallback: original message
88		}
89		return strings.Join(kept, "\n")
90	}
91	
92	// splitLogLine splits a timestamped log line (YYYY-MM-DDThh:mm:ssZ<sep>LEVEL<sep>message)
93	// into level and message. Handles tab and multi-space separators.
94	func splitLogLine(line string) (level, message string) {
95		// Skip past the timestamp — find first whitespace after opening chars
96		tEnd := strings.IndexAny(line, " \t")
97		if tEnd < 0 {
98			return "", line
99		}
100		rest := strings.TrimLeft(line[tEnd:], " \t")
101		lEnd := strings.IndexAny(rest, " \t")
102		if lEnd < 0 {
103			return rest, ""
104		}
105		return rest[:lEnd], strings.TrimLeft(rest[lEnd:], " \t")
106	}
107	
108	// formatScanErrorLine formats a FATAL/ERROR/WARN log message as "Error : <message>".
109	// For FATAL lines, Trivy prepends "Fatal error <sep> run error: " which is stripped.
110	func formatScanErrorLine(level, message string) string {
111		if strings.ToUpper(level) == "FATAL" {
112			if idx := strings.Index(message, "run error: "); idx >= 0 {
113				message = message[idx+len("run error: "):]
114			} else {
115				message = strings.TrimLeft(strings.TrimPrefix(message, "Fatal error"), " \t")
116			}
117		}
118		return "Error : " + message
119	}

