		body += section.Title + " " + section.Body + "\n"
	}

	for _, want := range []string{"CVE", "Secret", "License", "Misconfig"} {
		if !strings.Contains(body, want) {
			t.Errorf("the help does not explain the %s tab", want)
		}
	}
}

