package ociresources

import (
	"io"
	"log"
	"os"
	"testing"
	"time"

	"github.com/charmbracelet/bubbles/table"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/docker"
)

// Every command this view returns shells out to Docker, talks to a registry over
// HTTP or writes the scan cache. No test executes one: image, network, volume
// and registry lists, scan results and login statuses are fed in as messages,
// and the assertions are on model state.
//
// These tests drive Update() and View() only — update.go is 1698 lines and
// registry_browser.go 912, both due to be split, so assertions on their
// internals would pin the current layout.
//
// HOME is redirected for the whole package: the launch form and the registry
// list persist through config.Save, and the scan cache writes to ~/.devdesk.

func TestMain(m *testing.M) {
	log.SetOutput(io.Discard)

	home, err := os.MkdirTemp("", "devdesk-oci-test")
	if err != nil {
		log.SetOutput(os.Stderr)
		panic(err)
	}
	_ = os.Setenv("HOME", home)
	_ = os.Setenv("USERPROFILE", home)

	code := m.Run()

	_ = os.RemoveAll(home)
	log.SetOutput(os.Stderr)
	os.Exit(code)
}

func testConfig() *config.Config {
	cfg := config.Default()
	cfg.Registry.Registries = []config.RegistryItem{
		{URL: "registry.example.com", Username: "anthnel", Alias: "prod", AuthEnabled: true},
		{URL: "docker.io", Alias: "hub"},
	}
	return cfg
}

func at(day int) time.Time {
	return time.Date(2026, 8, day, 12, 0, 0, 0, time.UTC)
}

// imageFixtures give every sortable column a total order — sort.Slice is not
// stable, so ties would make the expected sequences ambiguous. One image is
// untagged, which is the case Name() special-cases.
func imageFixtures() []docker.Image {
	return []docker.Image{
		{ID: "aaa1111", Repository: "api", Tag: "v1", Size: 400, UniqueSize: 40, Containers: 1},
		{ID: "bbb2222", Repository: "cache", Tag: "v2", Size: 300, UniqueSize: 30},
		{ID: "ccc3333", Repository: "web", Tag: "v3", Size: 200, UniqueSize: 20, Containers: 2},
		{ID: "ddd4444", Repository: "orphan", Tag: "<none>", Size: 100, UniqueSize: 10},
	}
}

func networkFixtures() []docker.Network {
	return []docker.Network{
		{ID: "net11111", Name: "bridge", Driver: "bridge", Scope: "local"},
		{ID: "net22222", Name: "devdesk", Driver: "bridge", Scope: "local"},
		{ID: "net33333", Name: "overlay-prod", Driver: "overlay", Scope: "swarm"},
	}
}

func volumeFixtures() []docker.Volume {
	return []docker.Volume{
		{Name: "pgdata", Driver: "local", Mountpoint: "/var/lib/docker/volumes/pgdata/_data"},
		{Name: "redis", Driver: "local", Mountpoint: "/var/lib/docker/volumes/redis/_data"},
	}
}

// scanCacheFixture covers the three states a row can be in: scanned clean,
// scanned with findings, and never scanned (absent from the map).
func scanCacheFixture() map[string]cache.ImageScanEntry {
	return map[string]cache.ImageScanEntry{
		"api:v1":   {Critical: 2, High: 3, Medium: 4, Low: 5, ScannedAt: at(1)},
		"cache:v2": {ScannedAt: at(2)},
	}
}

// newTestModel returns a laid-out model with no data yet.
func newTestModel(t *testing.T) Model {
	t.Helper()
	return feed(t, New(testConfig()), tea.WindowSizeMsg{Width: 180, Height: 30})
}

// loadedModel returns a model holding every tab's fixtures and the scan cache.
func loadedModel(t *testing.T) Model {
	t.Helper()
	return feed(t, newTestModel(t),
		ImagesListMsg{Images: imageFixtures()},
		ScanCacheLoadedMsg{Entries: scanCacheFixture()},
		NetworksListMsg{Networks: networkFixtures()},
		VolumesListMsg{Volumes: volumeFixtures()},
	)
}

func feed(t *testing.T, m Model, msgs ...tea.Msg) Model {
	t.Helper()
	for _, msg := range msgs {
		m, _ = step(t, m, msg)
	}
	return m
}

func step(t *testing.T, m Model, msg tea.Msg) (Model, tea.Cmd) {
	t.Helper()
	next, cmd := m.Update(msg)
	updated, ok := next.(Model)
	if !ok {
		t.Fatalf("Update() returned %T, want ociresources.Model", next)
	}
	return updated, cmd
}

// cells returns column col of every table row.
func cells(rows []table.Row, col int) []string {
	out := make([]string, 0, len(rows))
	for _, row := range rows {
		out = append(out, row[col])
	}
	return out
}

func equal(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

package ociresources

import (
	"errors"
	"strings"
	"testing"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/scan"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// ── Construction and loading ─────────────────────────────────────────────────

func TestNewOpensOnImagesSortedByName(t *testing.T) {
	m := New(testConfig())

	if m.activeTab != tabImages {
		t.Errorf("activeTab = %d on a new model, want the images tab", m.activeTab)
	}
	if m.sortColumn != sortByName || !m.sortAsc {
		t.Errorf("sort = (%d, asc=%v), want name ascending", m.sortColumn, m.sortAsc)
	}
	if !m.loading || !m.loadingNets || !m.loadingVols {
		t.Error("a new model is not marked loading on every tab")
	}
	// The registries come from config rather than from Docker, so they are
	// present before any command runs.
	if len(m.registries) != 2 {
		t.Errorf("registries = %v, want the configured two", m.registries)
	}
}

func TestInitLoadsEveryTab(t *testing.T) {
	if cmd := New(testConfig()).Init(); cmd == nil {
		t.Fatal("Init() issued no commands")
	}
}

func TestListsFillTheirTables(t *testing.T) {
	m := loadedModel(t)

	if m.loading || m.loadingNets || m.loadingVols {
		t.Error("still loading after every list arrived")
	}
	if got := cells(m.imageTable.Rows(), 1); len(got) != 4 {
		t.Errorf("the image table holds %v", got)
	}
	if got := cells(m.networkTable.Rows(), 1); !equal(got, []string{"bridge", "devdesk", "overlay-prod"}) {
		t.Errorf("the network table holds %v", got)
	}
	if got := cells(m.volumeTable.Rows(), 0); !equal(got, []string{"pgdata", "redis"}) {
		t.Errorf("the volume table holds %v", got)
	}
}

// A Docker failure has to clear the spinner as well as report, or the tab shows
// a spinner forever.
func TestListFailuresStopTheSpinner(t *testing.T) {
	tests := []struct {
		name string
		msg  tea.Msg
		busy func(Model) bool
	}{
		{"images", ImagesListMsg{Err: errors.New("docker daemon not running")}, func(m Model) bool { return m.loading }},
		{"networks", NetworksListMsg{Err: errors.New("docker daemon not running")}, func(m Model) bool { return m.loadingNets }},
		{"volumes", VolumesListMsg{Err: errors.New("docker daemon not running")}, func(m Model) bool { return m.loadingVols }},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			m := feed(t, newTestModel(t), tt.msg)

			if tt.busy(m) {
				t.Error("still loading after the failure")
			}
			if m.errorMsg == "" {
				t.Error("the failure was not reported")
			}
		})
	}
}

// An untagged image is "<repository>" rather than "repository:<none>", which is
// also the key the scan cache is looked up under.
func TestUntaggedImagesDropTheTagSuffix(t *testing.T) {
	m := loadedModel(t)

	names := cells(m.imageTable.Rows(), 1)
	for _, name := range names {
		if strings.Contains(name, "<none>") {
			t.Errorf("the table shows a raw <none> tag: %v", names)
		}
	}
}

// ── Tabs ─────────────────────────────────────────────────────────────────────

func TestTabCyclesForwardAndBack(t *testing.T) {
	m := loadedModel(t)

	for _, want := range []ociTab{tabNetworks, tabVolumes, tabRegistries, tabImages} {
		m = feed(t, m, testutil.Key("tab"))
		if m.activeTab != want {
			t.Fatalf("tab landed on %d, want %d", m.activeTab, want)
		}
	}

	m = feed(t, m, testutil.Key("shift+tab"))
	if m.activeTab != tabRegistries {
		t.Errorf("shift+tab landed on %d, want it to wrap backwards", m.activeTab)
	}
}

// Only the active tab's table takes the keyboard, or arrow keys would move two
// cursors at once.
func TestOnlyTheActiveTablesIsFocused(t *testing.T) {
	m := loadedModel(t)
	if !m.imageTable.Focused() {
		t.Error("the image table is not focused on the images tab")
	}

	m = feed(t, m, testutil.Key("tab"))
	if m.imageTable.Focused() {
		t.Error("the image table kept focus after switching away")
	}
	if !m.networkTable.Focused() {
		t.Error("the network table did not take focus")
	}
}

// ── Images: sorting and filtering ────────────────────────────────────────────

func TestSortCyclesDirectionThenColumn(t *testing.T) {
	m := loadedModel(t)

	m = feed(t, m, testutil.Key("."))
	if m.sortColumn != sortByName || m.sortAsc {
		t.Errorf("after one '.', sort = (%d, asc=%v), want the same column reversed", m.sortColumn, m.sortAsc)
	}

	m = feed(t, m, testutil.Key("."))
	if m.sortColumn != sortByDiskUsage || !m.sortAsc {
		t.Errorf("after two '.', sort = (%d, asc=%v), want the next column ascending", m.sortColumn, m.sortAsc)
	}
}

func TestSortReordersTheImages(t *testing.T) {
