13	// editingView stands in for any view with a focused text input. It records the
14	// keys the router forwards to it, which is how the tests tell "the view got the
15	// keystroke" apart from "the router swallowed it".
16	type editingView struct {
17		editing  bool
18		received []string
19	}
20	
21	func (v *editingView) Init() tea.Cmd { return nil }
22	
23	func (v *editingView) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
24		if key, ok := msg.(tea.KeyMsg); ok {
25			v.received = append(v.received, key.String())
26		}
27		return v, nil
28	}
29	
30	func (v *editingView) View() string       { return "" }
31	func (v *editingView) InEditMode() bool   { return v.editing }
32	func (v *editingView) keysSeen() []string { return v.received }
33	
34	// routerWith builds the smallest App that can route a key: a current view and a
35	// command input. The real constructor builds every view in the application,
36	// several of which shell out to Docker.
37	func routerWith(view tea.Model) *App {
38		return &App{
39			currentView:  command.ViewDashboard,
40			views:        map[command.ViewType]tea.Model{command.ViewDashboard: view},
41			commandInput: textinput.New(),
42			width:        120,
43			height:       40,
44		}
45	}
46	
47	// The point of the binding: a focused text input cannot claim it. Typing a URL
48	// like https://trivy-server:4954 needs ":" to stay an ordinary character, so
49	// alt+: is the only key that can be authoritative.
50	func TestAltColonEntersCommandModeFromInsideATextField(t *testing.T) {
51		view := &editingView{editing: true}
52		a := routerWith(view)
53	
54		a.handleKeyMsg(testutil.Key(altCommandModeKey))
55	
56		if !a.commandMode {
57			t.Fatal("alt+: did not open the command line while the view was editing")
58		}
59		if len(view.keysSeen()) != 0 {
60			t.Errorf("alt+: was forwarded to the view as %v; the router must consume it", view.keysSeen())
61		}
62	}
63	
64	func TestAltColonEntersCommandModeWithNothingFocused(t *testing.T) {
65		a := routerWith(&editingView{editing: false})
66	
67		a.handleKeyMsg(testutil.Key(altCommandModeKey))
68	
69		if !a.commandMode {
70			t.Error("alt+: did not open the command line")
71		}
72	}
73	
74	// A bare ":" keeps its old, conditional behaviour so muscle memory survives.
75	func TestBareColonStillDependsOnTheView(t *testing.T) {
76		t.Run("nothing focused, it opens the command line", func(t *testing.T) {
77			view := &editingView{editing: false}
78			a := routerWith(view)
79	
80			a.handleKeyMsg(testutil.Key(":"))
81	
82			if !a.commandMode {
83				t.Error(": did not open the command line with nothing focused")
84			}
85			if len(view.keysSeen()) != 0 {
86				t.Errorf(": was forwarded to the view as %v as well as opening the command line", view.keysSeen())
87			}
88		})
89	
90		t.Run("editing, it reaches the field", func(t *testing.T) {
91			view := &editingView{editing: true}
92			a := routerWith(view)
93	
94			a.handleKeyMsg(testutil.Key(":"))
95	
96			if a.commandMode {
97				t.Error(": opened the command line while a text field was focused")
98			}
