105	// Entering command mode asks for a re-layout: the command line replaces the
106	// inactive prompt, and a stale height leaves the viewport one row off.
107	func TestEnteringCommandModeRequestsAResize(t *testing.T) {
108		a := routerWith(&editingView{editing: true})
109	
