1	package app
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/anthnel/devdesk/internal/ui/shortcut"
8		"github.com/anthnel/devdesk/internal/ui/theme"
9		"github.com/charmbracelet/lipgloss"
10	)
11	
12	// HeaderView est l'interface que chaque vue doit implémenter pour fournir les données du header
13	type HeaderView interface {
14		GetShortcuts() shortcut.Shortcuts
15		GetTitle() string
16		GetIcon() string
17		GetHeaderInfo(context string) []shortcut.HeaderInfo
18	}
19	
20	// FooterView is implemented by views that have footer content rendered below the viewport border (Rule 124).
21	// The footer can contain a tab bar (1 line) and optionally an empty line + info line (2 lines).
22	type FooterView interface {
23		GetFooterHeight() int          // current footer height in lines (0 if no footer)
24		RenderFooter(width int) string // rendered footer content
25	}
26	
27	// headerMinHeight est la hauteur fixe du header (sans la ligne de commande).
28	const headerMinHeight = 7
29	
30	// ASCII logo for the header
31	var logoLines = []string{
32		`    ____            ____            __  `,
33		`   / __ \___ _   __/ __ \___  _____/ /__`,
34		`  / / / / _ \ | / / / / / _ \/ ___/ //_/`,
35		` / /_/ /  __/ |/ / /_/ /  __(__  ) ,<   `,
36		`/_____/\___/|___/_____/\___/____/_/|_|  `,
37	}
38	
39	const logoWidth = 40 // max width of a logo line
40	
41	// renderHeader generates the header (fixed height) followed by the command line (1 line).
42	func (a *App) renderHeader() string {
43		if view, ok := a.views[a.currentView]; ok {
44			if headerView, implementsHeaderView := view.(HeaderView); implementsHeaderView {
45				shortcuts := headerView.GetShortcuts()
46				info := headerView.GetHeaderInfo(a.currentContext)
47	
48				header := renderHeaderContent(info, shortcuts, a.width)
49	
50				pad := theme.Bg(" ")
51				var cmdLine string
52				if a.commandMode {
53					a.commandInput.Focus()
54					cmdLine = pad + theme.CommandLineStyle.Width(a.width-2).Render(a.renderCommandLineWithCompletion()) + pad
55				} else {
56					cmdLine = pad + theme.CommandLineInactiveStyle.Width(a.width-2).Render(":") + pad
57				}
58	
59				return header + "\n" + theme.EmptyLineBg(a.width) + "\n" + cmdLine
60			}
61		}
62	
63		return ""
64	}
65	
66	// renderHeaderContent generates the header block with a fixed height (headerMinHeight).
67	// Layout: 3 columns — info (25%), shortcuts (flexible), logo (fixed width).
68	func renderHeaderContent(info []shortcut.HeaderInfo, shortcuts shortcut.Shortcuts, width int) string {
69		innerWidth := width - 2 // 1 padding each side
70	
71		// Column widths
72		col1Width := innerWidth / 4
73		col3Width := logoWidth
74		col2Width := innerWidth - col1Width - col3Width
75		if col2Width < 0 {
76			col2Width = 0
77		}
78	
79		// Build column 1: key-value info lines
80		col1Lines := buildInfoLines(info, col1Width)
81	
82		// Build column 2: shortcuts
83		col2Lines := buildShortcutLines(shortcuts, col2Width)
84	
85		// Build column 3: logo (centered vertically — 1 empty line on top since 6 logo lines / 7 header lines)
86		col3Lines := buildLogoLines(col3Width)
87	
88		// Assemble rows
89		rows := make([]string, headerMinHeight)
90		for i := 0; i < headerMinHeight; i++ {
91			c1 := ""
92			if i < len(col1Lines) {
93				c1 = col1Lines[i]
94			}
95			c2 := ""
96			if i < len(col2Lines) {
97				c2 = col2Lines[i]
98			}
99			c3 := ""
100			if i < len(col3Lines) {
101				c3 = col3Lines[i]
102			}
103	
104			pad := theme.Bg(" ")
105			row := pad + theme.PadWithBg(c1, col1Width) + theme.PadWithBg(c2, col2Width) + theme.PadWithBg(c3, col3Width) + pad
106			rows[i] = row
