282		current := a.completionSuggestions[a.completionIndex]
283		currentInput := a.commandInput.Value()
284	
285		previewText := ""
286		if strings.HasPrefix(strings.ToLower(current.Text), strings.ToLower(currentInput)) &&
287			len(currentInput) > 0 {
288			previewText = current.Text[len(currentInput):]
289		}
