291		cmdBgStyle := lipgloss.NewStyle().Background(theme.ColorCmdLineBg)
292	
293		preview := cmdBgStyle.Foreground(theme.ColorDim).Render(previewText)
294	
295		hint := cmdBgStyle.Foreground(theme.ColorDim).Italic(true).
296			Render(fmt.Sprintf(" %s [%d/%d]",
297				current.Display,
298				a.completionIndex+1,
299				len(a.completionSuggestions)))
300	
301		contentWidth := lipgloss.Width(inputView) + lipgloss.Width(preview)
302		hintWidth := lipgloss.Width(hint)
303		// width - 2 (outer padding) - 2 (CommandLineStyle inner Padding(0,1,0,1))
304		spacerWidth := (a.width - 4) - contentWidth - hintWidth
305		spacer := ""
306		if spacerWidth > 0 {
307			spacer = cmdBgStyle.Render(strings.Repeat(" ", spacerWidth))
308		}
309	
310		return inputView + preview + spacer + hint
