package app

import (
	"strings"
	"testing"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// ── Assembly ─────────────────────────────────────────────────────────────────

// Rule 124: header, title border, viewport, footer — in that order, all of it
// inside the window.
func TestTheViewIsAssembledInOrder(t *testing.T) {
	a := router(t, &fakeView{
		title:        "OCI Resources",
		body:         "the table body",
		footerHeight: 2,
		footer:       "Images  Networks",
	})

	rendered := a.View()

	header := strings.Index(rendered, "DevDesk")
	if header == -1 {
		header = 0 // the ASCII logo is styled; fall back to position 0
	}
	title := strings.Index(rendered, "OCI Resources")
	body := strings.Index(rendered, "the table body")
	footer := strings.Index(rendered, "Images  Networks")

	if title == -1 || body == -1 || footer == -1 {
		t.Fatalf("title=%d body=%d footer=%d; something is missing from:\n%s", title, body, footer, rendered)
	}
	if !(title < body && body < footer) {
		t.Errorf("order is title=%d body=%d footer=%d, want title before body before footer", title, body, footer)
	}
}

// The window is filled exactly. A view rendering short would leave the
// terminal's own background showing below it (Rule 115).
func TestTheViewFillsTheWindow(t *testing.T) {
	for _, size := range [][2]int{{100, 30}, {180, 40}, {240, 60}} {
		a := routerAt(t, &fakeView{footerHeight: 2, body: "x"}, size[0], size[1])

		rendered := a.View()

		if got := lipgloss.Height(rendered); got != size[1] {
			t.Errorf("at %dx%d the view is %d rows, want %d", size[0], size[1], got, size[1])
		}
	}
}

// A view that has not been built yet says so instead of rendering blank, which
// would look like a hang.
func TestAMissingViewSaysSo(t *testing.T) {
	a := router(t, &fakeView{})
	a.currentView = command.ViewSecurity // never built

	if rendered := a.View(); !strings.Contains(rendered, "View not found") {
		t.Errorf("a missing view rendered:\n%s", rendered)
	}
}

// A view with no title still gets its border line, or the viewport loses its
// top edge.
func TestTheTitleLineIsDrawnWithoutATitle(t *testing.T) {
	withTrueColor(t)
	titled := router(t, &fakeView{title: "Workspaces", footerHeight: 2}).View()
	untitled := router(t, &bareView{}).View()

	if !strings.Contains(titled, "Workspaces") {
		t.Error("the title is missing from the border line")
	}
	if !strings.Contains(untitled, "─") {
		t.Error("a view with no title lost its top border line")
	}
}

// A view with no footer contributes none, rather than an empty line that would
// shift the layout by one row.
func TestAViewWithoutAFooterAddsNothing(t *testing.T) {
	withFooter := lipgloss.Height(router(t, &fakeView{footerHeight: 1, footer: "tabs"}).View())
	without := lipgloss.Height(router(t, &bareView{}).View())

	if withFooter != without {
		t.Errorf("the window is %d rows with a footer and %d without; both must fill it",
			withFooter, without)
	}
}

// ── Overlay precedence ───────────────────────────────────────────────────────

// An open overlay replaces the view rather than being drawn over part of it:
// the table underneath would still be readable and invite a keypress that goes
// nowhere.
func TestAnOpenOverlayReplacesTheView(t *testing.T) {
	tests := []struct {
		name string
		open func(*App)
		want string
	}{
		{"help", func(a *App) { a.handleKeyMsg(testutil.Key("?")) }, "Test Help"},
		{"context list", func(a *App) {
			a.Update(ContextListMsg{Contexts: []string{"default"}, Current: "default"})
		}, "Select Context"},
		{"theme list", func(a *App) {
			a.Update(ThemeListMsg{Themes: []string{"default"}, Current: "default"})
		}, "Select Theme"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			a := router(t, &fakeView{
				body:        "the table body",
				helpContent: help.Content{Title: "Test Help"},
			})
			tt.open(a)

			rendered := a.View()

			if !strings.Contains(rendered, tt.want) {
				t.Errorf("the %s overlay is not on screen:\n%s", tt.name, rendered)
			}
			if strings.Contains(rendered, "the table body") {
				t.Errorf("the view is still readable behind the %s overlay", tt.name)
			}
		})
	}
}

// Help is rendered first, matching the order the key handler checks them in —
// otherwise esc would close one overlay while another stayed on screen.
func TestHelpIsRenderedBeforeTheLists(t *testing.T) {
	a := router(t, &fakeView{helpContent: help.Content{Title: "Test Help"}})
	a.showContextList = true
	a.contextList = []string{"default"}
	a.handleKeyMsg(testutil.Key("?"))

	rendered := a.View()

	if !strings.Contains(rendered, "Test Help") {
		t.Error("the context list was drawn over the help overlay")
	}
}

// ── Rule 136: the filter bar joins the viewport ──────────────────────────────

// The viewport's bottom corners become T-junctions when the view below has a
// filter bar, so the two form one closed rectangle instead of two stacked
// boxes.
func TestTheFilterBarClosesTheRectangle(t *testing.T) {
	withTrueColor(t)
	plain := router(t, &fakeView{footerHeight: 2, footer: "info"}).View()
	filtering := router(t, &fakeView{footerHeight: 3, footer: "filter", filterBar: true}).View()

	if !strings.Contains(plain, "└") {
		t.Error("the plain viewport has no bottom-left corner")
	}
	if strings.Contains(filtering, "└") {
		t.Error("the corner was not turned into a T-junction for the filter bar")
	}
	if !strings.Contains(filtering, "├") || !strings.Contains(filtering, "┤") {
		t.Error("the filter bar does not join the viewport border")
	}
}

func TestReplaceViewportBottomCornersTouchesOnlyTheLastLine(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"a bordered box", "┌──┐\n│  │\n└──┘", "┌──┐\n│  │\n├──┤"},
		{"a single line has no bottom border", "└──┘", "└──┘"},
		{"corners above the last line are left alone", "└─┘\n│x│\n└─┘", "└─┘\n│x│\n├─┤"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := replaceViewportBottomCorners(tt.in); got != tt.want {
				t.Errorf("got %q, want %q", got, tt.want)
			}
		})
	}
}

package app

import (
	tea "github.com/charmbracelet/bubbletea"
)

// altCommandModeKey enters command mode from anywhere, including from a focused
// text input. Alt is used rather than Ctrl because a terminal encodes Ctrl only
// for ASCII 0x40-0x5F; ":" is 0x3A, so "ctrl+:" never reaches the application.
const altCommandModeKey = "alt+:"

// handleKeyMsg processes keyboard input
func (a *App) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	// Si un overlay est affiché, gérer la navigation
	if a.showHelp {
		return a.handleHelpKeyMsg(msg)
	}
	if a.showContextList {
		return a.handleContextListKeyMsg(msg)
	}
	if a.showThemeList {
		return a.handleThemeListKeyMsg(msg)
	}

	if a.commandMode {
		return a.handleCommandMode(msg)
	}

	switch msg.String() {
	case "ctrl+c":
		return a, tea.Quit
	case "q":
		cmd := a.maybeQuitApplication(msg)
		return a, cmd
	case "?":
		return a.maybeOpenHelp(msg)
	case altCommandModeKey:
		// The authoritative way in: handled here, before any InEditMode() check,
		// so no text input can claim it. A bare ":" cannot play that role — it is
		// an ordinary character in a field holding https://trivy-server:4954.
		return a, a.enterCommandMode()
	case ":":
		cmd := a.maybeEnterInCommandMode(msg)
		return a, cmd
	case "esc":
		cmd := a.maybeQuitCommandMode(msg)
		// Rule 124: re-resize if a form was closed and footer height changed
		if newFooterHeight := a.getFooterHeight(); newFooterHeight != a.lastFooterHeight {
			a.resize(a.width, a.height)
		}
		return a, cmd
	default:
		return a, a.forwardToActiveView(msg)
	}
}

// forwardToActiveView hands a message to the current view and re-measures the
// layout when the view's footer changed shape in response (Rule 124) — opening
// a filter bar is the case that matters.
func (a *App) forwardToActiveView(msg tea.Msg) tea.Cmd {
	view, ok := a.views[a.currentView]
	if !ok {
		return nil
	}
	updatedView, cmd := view.Update(msg)
	a.views[a.currentView] = updatedView
	if newFooterHeight := a.getFooterHeight(); newFooterHeight != a.lastFooterHeight {
		a.resize(a.width, a.height)
	}
	return cmd
}

// enterCommandMode opens the command line unconditionally and asks for a
// re-layout, since the command line replaces the inactive prompt.
//
// Focus is taken here rather than while rendering: a bubbles/textinput drops
// every key it receives while blurred, so granting focus from View() would make
// the command line depend on a render having happened first (Rule 110 — View()
// is read-only).
func (a *App) enterCommandMode() tea.Cmd {
	a.commandMode = true
	a.commandInput.Reset()
	a.commandInput.Focus()
	return a.requestResize()
}

// inEditMode reports whether the active view has a focused field, which is what
// decides whether the router claims a key or passes it on.
func (a *App) inEditMode() bool {
	view, ok := a.views[a.currentView]
	if !ok {
		return false
	}
	formView, implements := view.(FormView)
	return implements && formView.InEditMode()
}

// maybeEnterInCommandMode answers a bare ":", which only opens the command line
// when nothing is being edited — inside a text input ":" is an ordinary
// character. Use altCommandModeKey to get in from anywhere.
func (a *App) maybeEnterInCommandMode(msg tea.Msg) tea.Cmd {
	if _, ok := a.views[a.currentView]; !ok {
		return nil
	}
	if !a.inEditMode() {
		return a.enterCommandMode()
	}
	return a.forwardToActiveView(msg)
}

func (a *App) maybeQuitCommandMode(msg tea.Msg) tea.Cmd {
	if _, ok := a.views[a.currentView]; !ok {
		return nil
	}
	if !a.inEditMode() {
		a.commandMode = false
		a.commandInput.Reset()
		a.commandInput.Blur()
		return a.requestResize()
	}
	return a.forwardToActiveView(msg)
}

func (a *App) maybeQuitApplication(msg tea.Msg) tea.Cmd {
	if _, ok := a.views[a.currentView]; !ok {
		return nil
	}
	if !a.inEditMode() {
		return tea.Quit
	}
	return a.forwardToActiveView(msg)
}

package app

import (
	"log"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/ui/containers"
	"github.com/anthnel/devdesk/internal/ui/dashboard"
	"github.com/anthnel/devdesk/internal/ui/gitlab/auth"
	"github.com/anthnel/devdesk/internal/ui/gitlab/explorer"
	"github.com/anthnel/devdesk/internal/ui/netdiag"
	ociresources "github.com/anthnel/devdesk/internal/ui/oci_resources"
	"github.com/anthnel/devdesk/internal/ui/security"
	"github.com/anthnel/devdesk/internal/ui/status"
	"github.com/anthnel/devdesk/internal/ui/workspaces"
	"github.com/anthnel/devdesk/internal/credentials"
)

// handleCommandMode gère le mode commande
func (a *App) handleCommandMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.Type {
	case tea.KeyEsc:
		return a, a.closeCommandLine()

	case tea.KeyTab:
		// Cycle à travers les suggestions
		return a.handleCompletionCycle()

	case tea.KeyEnter:
		return a.runCommand()

	default:
		// Mettre à jour l'input
		var cmd tea.Cmd
		a.commandInput, cmd = a.commandInput.Update(msg)
		// Mettre à jour les suggestions après chaque frappe
		a.updateCompletions()
		return a, cmd
	}
}

// closeCommandLine leaves command mode and asks for the re-layout that gives
// the row back to the inactive prompt.
func (a *App) closeCommandLine() tea.Cmd {
	a.commandMode = false
	a.commandInput.Blur()
	a.resetCompletion()
	return a.requestResize()
}

// runCommand executes what the command line holds — or the highlighted
// suggestion, which is what makes tab-then-enter work.
func (a *App) runCommand() (tea.Model, tea.Cmd) {
	input := a.commandInput.Value()
	if len(a.completionSuggestions) > 0 {
		input = a.completionSuggestions[a.completionIndex].Text
	}

	cmd := command.ParseCommand(input)

	switch cmd.Type {
	case command.CommandQuit:
		a.resetCompletion()
		return a, tea.Quit

	case command.CommandView:
		a.commandMode = false
		a.commandInput.Blur()
		a.resetCompletion()
		a.resetSelectionModeFor(cmd.View)
		return a, a.switchView(cmd.View)

	case command.CommandContext:
		a.commandMode = false
		a.commandInput.Blur()
		a.resetCompletion()
		if len(cmd.Args) > 0 {
			// Créer/switch vers un contexte nommé
			return a, a.switchContext(cmd.Args[0])
		}
		// Pas d'args → ouvrir la modale interactive
		return a, a.listContexts()

	case command.CommandTheme:
		// Ouvrir la modale interactive de sélection de thème
		a.commandMode = false
		a.commandInput.Blur()
		a.resetCompletion()
		return a, a.listThemes()

	case command.CommandUnknown:
		// Commande invalide - rester en mode commande
		return a, nil
	}

	return a, nil
}

// resetSelectionModeFor takes a view out of selection mode before switching to
// it. Workspaces is dropped and rebuilt; the OCI view is reset in place because
// it holds scan results worth keeping.
func (a *App) resetSelectionModeFor(view command.ViewType) {
	switch view {
	case command.ViewWorkspaces:
		delete(a.views, view)
	case command.ViewOCIResources:
		if existing, ok := a.views[command.ViewOCIResources]; ok {
			updatedView, _ := existing.Update(ociresources.ResetSelectionMsg{})
			a.views[command.ViewOCIResources] = updatedView
		}
	}
}

// switchView change la vue courante
func (a *App) switchView(view command.ViewType) tea.Cmd {
	// Lazy loading des vues
	if _, exists := a.views[view]; !exists {
		a.createView(view)
	}

	a.currentView = view

	newView, ok := a.views[view]
	if !ok {
		return nil
	}
	log.Printf("Switching to view: %s, calling Init()", view)

	// Init() + un WindowSizeMsg pour forcer le redimensionnement
	return tea.Batch(newView.Init(), a.requestResize())
}

// createView crée une vue (lazy loading)
func (a *App) createView(view command.ViewType) {
	if _, exists := a.views[view]; exists && view != command.ViewGitlabAuth {
		return
	}

	switch view {
	case command.ViewDashboard:
		a.views[view] = dashboard.New(a.config, a.sharedState)
	case command.ViewStatus:
		a.views[view] = status.New(a.config)
	case command.ViewGitlabAuth:
		a.views[view] = a.newAuthView()
	case command.ViewGitlabExplorer:
		a.views[view] = explorer.New(a.config, a.sharedState)
	case command.ViewWorkspaces:
		a.views[view] = workspaces.New(a.config)
	case command.ViewSecurity:
		a.views[view] = security.New(a.config)
	case command.ViewContainers:
		a.views[view] = containers.New(a.config)
	case command.ViewOCIResources:
		a.views[view] = ociresources.New(a.config)
	case command.ViewNet:
		a.views[view] = netdiag.New(a.config)
	}
}

// newAuthView builds the GitLab auth view against this context's credentials.
// It is rebuilt on every switch rather than cached, so the form reflects the
// session that is current now.
func (a *App) newAuthView() tea.Model {
	storage := credentials.NewChainStorage(
		credentials.NewFileStorageForContext(a.currentContext),
		credentials.NewGitCredentialStorageWithContext(a.currentContext),
	)
	log.Printf("Creating GitLab auth view with context: %s", a.currentContext)

	authView := auth.New(a.config, storage)
	if a.sharedState.GitLabClient != nil && a.sharedState.CurrentUser != nil {
		authView.SetAuth(a.sharedState.GitLabClient, a.sharedState.CurrentUser)
	}
	return authView
}

// updateCompletions met à jour les suggestions basées sur l'input actuel
func (a *App) updateCompletions() {
	input := a.commandInput.Value()

	// Reset index si input change
	if input != a.completionInput {
		a.completionIndex = 0
		a.completionInput = input
	}

	a.completionSuggestions = a.completionEngine.GetSuggestions(input)
}

// handleCompletionCycle cycle à travers les suggestions (Tab répété)
func (a *App) handleCompletionCycle() (tea.Model, tea.Cmd) {
	if len(a.completionSuggestions) == 0 {
		return a, nil
	}

	// Increment avec wrap-around
	a.completionIndex = (a.completionIndex + 1) % len(a.completionSuggestions)
	return a, nil
}

// resetCompletion nettoie l'état de complétion
func (a *App) resetCompletion() {
	a.completionSuggestions = nil
	a.completionIndex = 0
	a.completionInput = ""
}

package app

import (
	"log"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	gitlabclient "gitlab.com/gitlab-org/api/client-go"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/credentials"
	"github.com/anthnel/devdesk/internal/gitlab"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ContextSwitchCompleteMsg signale le succès du switch de contexte
type ContextSwitchCompleteMsg struct {
	ContextName  string
	Config       *config.Config
	Created      bool // true si le contexte a été créé automatiquement
	GitLabClient *gitlabclient.Client
	GitLabUser   *gitlabclient.User
}

// ContextSwitchErrorMsg signale une erreur lors du switch
type ContextSwitchErrorMsg struct {
	Error error
}

// ContextListMsg contient la liste des contextes disponibles
type ContextListMsg struct {
	Contexts []string
	Current  string
}

// switchContext handles context switching with auto-creation
func (a *App) switchContext(contextName string) tea.Cmd {
	return func() tea.Msg {
		log.Printf("Context switch requested: %s", contextName)

		cfg, created, err := loadOrCreateContext(contextName)
		if err != nil {
			return ContextSwitchErrorMsg{Error: err}
		}

		glClient, glUser := autoLoginForContext(contextName, cfg)

		log.Printf("Context switch successful: %s (created: %v)", contextName, created)
		return ContextSwitchCompleteMsg{
			ContextName:  contextName,
			Config:       cfg,
			Created:      created,
			GitLabClient: glClient,
			GitLabUser:   glUser,
		}
	}
}

// loadOrCreateContext validates the name, creates the context when it does not
// exist yet, loads its configuration and persists it as current.
func loadOrCreateContext(contextName string) (*config.Config, bool, error) {
	if err := config.ValidateContextName(contextName); err != nil {
		log.Printf("ERROR: Context validation failed: %v", err)
		return nil, false, err
	}

	exists, err := config.ContextExists(contextName)
	if err != nil {
		log.Printf("ERROR: Failed to check context existence: %v", err)
		return nil, false, err
	}

	created := false
	if !exists {
		log.Printf("Context '%s' does not exist, creating automatically", contextName)
		if err := config.CreateContext(contextName); err != nil {
			log.Printf("ERROR: Failed to create context '%s': %v", contextName, err)
			return nil, false, err
		}
		created = true
		log.Printf("Context '%s' created successfully", contextName)
	}

	cfg, err := config.LoadContext(contextName)
	if err != nil {
		log.Printf("ERROR: Failed to load context '%s': %v", contextName, err)
		return nil, created, err
	}

	if err := config.SetCurrentContext(contextName); err != nil {
		log.Printf("ERROR: Failed to persist context switch: %v", err)
		return nil, created, err
	}

	return cfg, created, nil
}

// autoLoginForContext tries the new context's own credentials. A failure is not
// an error: the user is sent to the auth view instead.
func autoLoginForContext(contextName string, cfg *config.Config) (*gitlabclient.Client, *gitlabclient.User) {
	if cfg.GitLab.URL == "" {
		return nil, nil
	}

	storage := credentials.NewChainStorage(
		credentials.NewFileStorageForContext(contextName),
		credentials.NewGitCredentialStorageWithContext(contextName),
	)
	gitlabAuth := gitlab.NewAuth(storage)

	token, err := gitlabAuth.LoadCredentials(cfg.GitLab.URL)
	if err != nil || token == "" {
		token = cfg.GitLab.Token
	}
	if token == "" {
		return nil, nil
	}

	result, err := gitlabAuth.Authenticate(cfg.GitLab.URL, token, false)
	if err != nil {
		log.Printf("Auto-login failed for context '%s': %v", contextName, err)
		return nil, nil
	}
	log.Printf("Auto-login successful for context '%s': %s", contextName, result.User.Username)
	return result.Client, result.User
}

// listContexts retrieves available contexts
func (a *App) listContexts() tea.Cmd {
	return func() tea.Msg {
		log.Printf("Listing available contexts")
		contexts, err := config.ListContexts()
		if err != nil {
			log.Printf("ERROR: Failed to list contexts: %v", err)
			return ContextSwitchErrorMsg{Error: err}
		}

		current, _ := config.GetCurrentContext()
		if current == "" {
			current = "default"
		}

		log.Printf("Found %d contexts, current: %s", len(contexts), current)
		return ContextListMsg{Contexts: contexts, Current: current}
	}
}

// handleContextSwitchComplete processes successful context switches
func (a *App) handleContextSwitchComplete(msg ContextSwitchCompleteMsg) (tea.Model, tea.Cmd) {
	a.config = msg.Config
	a.currentContext = msg.ContextName

	// Reset GitLab auth state — the new context has its own credentials
	a.sharedState.GitLabClient = nil
	a.sharedState.IsAuthenticated = false
	a.sharedState.CurrentUser = nil
	a.sharedState.CachedGroups = nil
	a.sharedState.CachedProjects = nil
	a.sharedState.GitLabStats = nil

	// Apply auto-login result from the context switch if successful
	if msg.GitLabClient != nil && msg.GitLabUser != nil {
		a.sharedState.GitLabClient = msg.GitLabClient
		a.sharedState.CurrentUser = msg.GitLabUser
		a.sharedState.IsAuthenticated = true
	} else {
		// No credentials available — navigate to auth view for manual login
		a.currentView = command.ViewGitlabAuth
	}

	// Reinitialize views with new config; auth state is already populated above
	initCmd := a.reinitializeViews()

	return a, tea.Batch(a.requestResize(), initCmd)
}

// handleContextList opens the picker with the cursor on the context in use, so
// enter is a no-op rather than a switch to whatever sorts first.
func (a *App) handleContextList(msg ContextListMsg) (tea.Model, tea.Cmd) {
	a.showContextList = true
	a.contextList = msg.Contexts
	a.contextSelectedIdx = indexOf(msg.Contexts, msg.Current)
	return a, nil
}

// handleContextListKeyMsg gère les touches clavier dans l'overlay de sélection de contexte
func (a *App) handleContextListKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc", "q":
		a.showContextList = false
	case "up", "k":
		a.contextSelectedIdx = max(a.contextSelectedIdx-1, 0)
	case "down", "j":
		a.contextSelectedIdx = min(a.contextSelectedIdx+1, len(a.contextList)-1)
	case "enter":
		if len(a.contextList) > 0 {
			a.showContextList = false
			return a, a.switchContext(a.contextList[a.contextSelectedIdx])
		}
	}
	return a, nil
}

// renderContextListOverlay affiche un overlay avec la liste des contextes
func (a *App) renderContextListOverlay() string {
	return renderPickerOverlay("Select Context", a.contextList, a.currentContext, a.contextSelectedIdx)
}

// renderPickerOverlay draws the list overlays: a title, one entry per line, the
// entry in use marked and the highlighted one carrying the focus indicator.
func renderPickerOverlay(title string, entries []string, current string, selectedIdx int) string {
	var b strings.Builder

	b.WriteString(theme.TitleStyle.Render(title) + "\n\n")

	for i, entry := range entries {
		label := entry
		if entry == current {
			label += " (current)"
		}
		if i == selectedIdx {
			b.WriteString(theme.KeyStyle.Render(theme.IconCircleSmall + " " + label))
		} else {
			b.WriteString(theme.Bg("  " + label))
		}
		b.WriteString("\n")
	}

	return theme.OverlayBoxStyle().Render(b.String())
}

// indexOf returns the position of want, or 0 when it is absent — the cursor has
// to land on a row that exists.
func indexOf(entries []string, want string) int {
	for i, entry := range entries {
		if entry == want {
			return i
		}
	}
	return 0
}

