package app

import (
	"log"

	tea "github.com/charmbracelet/bubbletea"
	gitlabclient "gitlab.com/gitlab-org/api/client-go"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/credentials"
	"github.com/anthnel/devdesk/internal/gitlab"
	"github.com/anthnel/devdesk/internal/ui/gitlab/auth"
)

// GitLabAutoLoginMsg signale le résultat de l'auto-login
type GitLabAutoLoginMsg struct {
	Client *gitlabclient.Client
	User   *gitlabclient.User
	Error  error
}

// tryAutoLogin tente de se connecter automatiquement à GitLab avec les credentials sauvegardés
func (a *App) tryAutoLogin() tea.Cmd {
	url := a.config.GitLab.URL
	currentContext := a.currentContext
	fallbackToken := a.config.GitLab.Token

	// Si pas d'URL configurée, pas d'auto-login
	if url == "" {
		return nil
	}

	return func() tea.Msg {
		storage := credentials.NewChainStorage(
			credentials.NewFileStorageForContext(currentContext),
			credentials.NewGitCredentialStorageWithContext(currentContext),
		)
		gitlabAuth := gitlab.NewAuth(storage)

		// Essayer de charger le token depuis le storage, sinon la config
		token, err := gitlabAuth.LoadCredentials(url)
		if err != nil || token == "" {
			token = fallbackToken
			if token == "" {
				return GitLabAutoLoginMsg{}
			}
		}

		// false = ne pas re-sauvegarder
		result, err := gitlabAuth.Authenticate(url, token, false)
		if err != nil {
			log.Printf("Auto-login failed: %v", err)
			return GitLabAutoLoginMsg{Error: err}
		}

		log.Printf("Auto-login successful: %s", result.User.Username)
		return GitLabAutoLoginMsg{Client: result.Client, User: result.User}
	}
}

// handleAutoLoginResult applies a successful auto-login. A failure is ignored:
// the user can still authenticate by hand from the auth view.
func (a *App) handleAutoLoginResult(msg GitLabAutoLoginMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil || msg.Client == nil {
		return a, nil
	}

	log.Printf("GitLab auto-login successful for user: %s", msg.User.Username)
	a.setAuthenticated(msg.Client, msg.User)
	return a, nil
}

// handleAuthResult intercepts a manual authentication to persist the config and
// populate the shared state before the view sees it.
func (a *App) handleAuthResult(msg auth.AuthResultMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		// L'erreur est déjà gérée par la vue, juste transmettre le message
		return a, a.forwardToActiveView(msg)
	}

	log.Printf("GitLab authentication successful for user: %s", msg.User.Username)
	a.setAuthenticated(msg.Client, msg.User)

	if msg.ConfigToSave != nil {
		if err := config.Save(msg.ConfigToSave); err != nil {
			log.Printf("ERROR: Failed to save config after authentication: %v", err)
		} else {
			log.Printf("Config saved successfully (URL: %s, TokenSaved: %v)",
				msg.ConfigToSave.GitLab.URL, msg.SaveToConfig)
		}
	}

	// Transmettre le message à la vue pour mise à jour de l'UI
	return a, a.forwardToActiveView(msg)
}

// setAuthenticated records a live GitLab session in the shared state, which is
// what every GitLab-backed view reads to decide whether it can load anything.
func (a *App) setAuthenticated(client *gitlabclient.Client, user *gitlabclient.User) {
	a.sharedState.GitLabClient = client
	a.sharedState.CurrentUser = user
	a.sharedState.IsAuthenticated = true
}

package app

import (
	"log"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/command"
	ociresources "github.com/anthnel/devdesk/internal/ui/oci_resources"
	"github.com/anthnel/devdesk/internal/ui/security"
	"github.com/anthnel/devdesk/internal/ui/workspaces"
)

// Rule 126: opening a scanned item reads the cache; it never triggers a scan.
// The full result lives in its own file, so the metadata entry can outlive it —
// every load here has a fallback for that.

// handleWorkspaceScanDetails loads a cached workspace scan result from disk.
func (a *App) handleWorkspaceScanDetails(msg workspaces.ScanDetailsRequestMsg) (tea.Model, tea.Cmd) {
	repoPath := msg.RepoPath
	return a, func() tea.Msg {
		result, err := cache.LoadWorkspaceScanResult(repoPath)
		return WorkspaceScanResultLoadedMsg{Result: result, RepoPath: repoPath, Err: err}
	}
}

// handleScanDetailsRequest loads a cached image scan result from disk.
func (a *App) handleScanDetailsRequest(msg ociresources.ScanDetailsRequestMsg) (tea.Model, tea.Cmd) {
	log.Printf("Scan details requested for image: %s", msg.ImageName)
	imageName := msg.ImageName
	return a, func() tea.Msg {
		result, err := cache.LoadImageScanResult(imageName)
		return ImageScanResultLoadedMsg{Result: result, ImageName: imageName, Err: err}
	}
}

// handleWorkspaceScanResultLoaded opens the security view on the loaded result.
// When the result file is gone the view opens on its form with the repository
// filled in, so the user can rescan rather than face a dead end.
func (a *App) handleWorkspaceScanResultLoaded(msg WorkspaceScanResultLoadedMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil || msg.Result == nil {
		log.Printf("Workspace scan result not on disk for %s (fallback to input): %v", msg.RepoPath, msg.Err)
		return a, a.openSecurityView(
			security.NewWithTargetReturnToWorkspaces(a.config, msg.RepoPath),
			command.ViewWorkspaces,
		)
	}
	return a, a.openSecurityView(
		security.NewWithPreloadedResult(a.config, msg.Result),
		command.ViewWorkspaces,
	)
}

// handleImageScanResultLoaded opens the security view on the loaded result.
// When the result file is gone — an image scanned before results were persisted
// — the scan is started again rather than reported as empty.
func (a *App) handleImageScanResultLoaded(msg ImageScanResultLoadedMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil || msg.Result == nil {
		log.Printf("Image scan result not on disk for %s (fallback to scan): %v", msg.ImageName, msg.Err)
		cmd := a.openSecurityView(
			security.NewWithImageTarget(a.config, msg.ImageName, false),
			command.ViewOCIResources,
		)
		return a, tea.Batch(cmd, func() tea.Msg { return security.StartScanMsg{} })
	}
	return a, a.openSecurityView(
		security.NewWithPreloadedResult(a.config, msg.Result),
		command.ViewOCIResources,
	)
}

// openSecurityView installs a freshly built security view, records where esc
// should return to, and lays it out.
func (a *App) openSecurityView(view *security.Model, origin command.ViewType) tea.Cmd {
	view.OriginView = origin
	a.views[command.ViewSecurity] = view
	a.currentView = command.ViewSecurity
	return tea.Batch(view.Init(), a.requestResize())
}

// routeToOCIImagesView forwards a message to the OCI view even when it is not
// on screen, so a scan started there keeps progressing while the user is
// elsewhere.
func (a *App) routeToOCIImagesView(msg tea.Msg) (tea.Model, tea.Cmd) {
	view, ok := a.views[command.ViewOCIResources]
	if !ok {
		return a, nil
	}
	updatedView, cmd := view.Update(msg)
	a.views[command.ViewOCIResources] = updatedView
	return a, cmd
}

// handleLaunchScan switches to the OCI view and hands it the scan the security
// view delegated back.
func (a *App) handleLaunchScan(msg tea.Msg) (tea.Model, tea.Cmd) {
	if _, exists := a.views[command.ViewOCIResources]; !exists {
		a.createView(command.ViewOCIResources)
	}
	a.currentView = command.ViewOCIResources

	view, ok := a.views[command.ViewOCIResources]
	if !ok {
		return a, nil
	}
	updatedView, cmd := view.Update(msg)
	a.views[command.ViewOCIResources] = updatedView
	return a, tea.Batch(cmd, a.requestResize())
}

package app

import (
	"log"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/ui/gitlab/explorer"
	ociresources "github.com/anthnel/devdesk/internal/ui/oci_resources"
	"github.com/anthnel/devdesk/internal/ui/security"
	"github.com/anthnel/devdesk/internal/ui/workspaces"
)

// Selection mode lets one view borrow another to pick something — a scan
// target, a clone destination. The router remembers where to come back to and
// translates the answer into the message the borrower understands.

// pullDestinationPrompt is shown while the explorer borrows the workspaces view.
const pullDestinationPrompt = "Enter into a parent directory — the repo will be cloned inside it"

// handleSelectionRequest switches to workspaces or oci_resources in selection mode
func (a *App) handleSelectionRequest(msg security.SelectionRequestMsg) (tea.Model, tea.Cmd) {
	a.selectionReturnView = a.currentView

	switch msg.Type {
	case "directory":
		log.Printf("Selection request: switching to workspaces for directory selection")
		return a, a.openBrowser(command.ViewWorkspaces, workspaces.NewForSelection(a.config, msg.Message))
	case "image":
		log.Printf("Selection request: switching to OCI images for image selection")
		return a, a.openBrowser(command.ViewOCIResources, ociresources.NewForSelection(a.config, msg.Message))
	}
	return a, nil
}

// handleExplorerPullRequest borrows the workspaces view to pick a clone target.
func (a *App) handleExplorerPullRequest() (tea.Model, tea.Cmd) {
	a.selectionReturnView = a.currentView
	log.Printf("Explorer pull request: switching to workspaces for directory selection")
	return a, a.openBrowser(
		command.ViewWorkspaces,
		workspaces.NewForSelection(a.config, pullDestinationPrompt),
	)
}

// openBrowser installs a view built in selection mode and lays it out.
func (a *App) openBrowser(view command.ViewType, model tea.Model) tea.Cmd {
	a.views[view] = model
	a.currentView = view
	return tea.Batch(model.Init(), a.requestResize())
}

// handleDirectorySelected returns to the originating view with the chosen path.
func (a *App) handleDirectorySelected(msg workspaces.DirectorySelectedMsg) (tea.Model, tea.Cmd) {
	log.Printf("Directory selected: %s, returning to %s", msg.Path, a.selectionReturnView)
	a.leaveSelectionMode()

	var result tea.Msg = security.SelectionResultMsg{Path: msg.Path}
	if a.selectionReturnView == command.ViewGitlabExplorer {
		result = explorer.PullDestinationSelectedMsg{Path: msg.Path}
	}
	return a, a.returnToOrigin(result)
}

// handleImageSelected returns to the security view with the chosen image.
func (a *App) handleImageSelected(msg ociresources.ImageSelectedMsg) (tea.Model, tea.Cmd) {
	log.Printf("Image selected: %s, returning to %s", msg.ImageName, a.selectionReturnView)
	a.currentView = a.selectionReturnView
	a.resetSelectionModeFor(command.ViewOCIResources)

	return a, a.returnToOrigin(security.SelectionResultMsg{Path: msg.ImageName})
}

// handleSelectionCancelled returns to the originating view without changes.
func (a *App) handleSelectionCancelled() (tea.Model, tea.Cmd) {
	log.Printf("Selection cancelled, returning to %s", a.selectionReturnView)
	a.leaveSelectionMode()

	var cancel tea.Msg = security.SelectionCancelledMsg{}
	if a.selectionReturnView == command.ViewGitlabExplorer {
		cancel = explorer.PullSelectionCancelledMsg{}
	}
	return a, a.returnToOrigin(cancel)
}

// leaveSelectionMode takes both borrowable views out of it. Workspaces is
// dropped so it is rebuilt normally; the OCI view is reset in place because it
// holds scan results worth keeping.
func (a *App) leaveSelectionMode() {
	a.currentView = a.selectionReturnView
	delete(a.views, command.ViewWorkspaces)
	a.resetSelectionModeFor(command.ViewOCIResources)
}

// returnToOrigin delivers the outcome to the view that asked and lays it out.
func (a *App) returnToOrigin(msg tea.Msg) tea.Cmd {
	view, ok := a.views[a.currentView]
	if !ok {
		return nil
	}
	updatedView, cmd := view.Update(msg)
	a.views[a.currentView] = updatedView
	a.viewport.GotoTop()
	return tea.Batch(cmd, a.requestResize())
}

package app

import (
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// helpViewportMinHeight keeps the overlay usable on a short window; below it
// the border and the scroll hint would leave no room for content.
const helpViewportMinHeight = 10

// helpOverlayMargin is the room the overlay box's border and padding take from
// the window, horizontally and vertically.
const helpOverlayMargin = 6

// maybeOpenHelp opens the help overlay for the active view, unless a field is
// focused — there "?" is a character to type.
func (a *App) maybeOpenHelp(msg tea.Msg) (tea.Model, tea.Cmd) {
	if _, ok := a.views[a.currentView]; !ok {
		return a, nil
	}
	if a.inEditMode() {
		return a, a.forwardToActiveView(msg)
	}

	provider, implements := a.views[a.currentView].(help.Provider)
	if !implements {
		return a, nil
	}

	height := max(a.height-helpOverlayMargin, helpViewportMinHeight)
	a.helpViewport = viewport.New(a.width-helpOverlayMargin, height)
	a.helpViewport.SetContent(help.Render(provider.GetHelpContent(), a.width))
	a.showHelp = true
	return a, nil
}

// handleHelpKeyMsg gère les touches clavier dans l'overlay d'aide
func (a *App) handleHelpKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc", "q", "?":
		a.showHelp = false
		return a, nil
	default:
		// Déléguer au viewport pour le scroll (↑↓/jk/PgUp/PgDn/g/G)
		var cmd tea.Cmd
		a.helpViewport, cmd = a.helpViewport.Update(msg)
		return a, cmd
	}
}

// renderHelpOverlay affiche un overlay avec l'aide de la vue courante
func (a *App) renderHelpOverlay() string {
	return theme.OverlayBoxStyle().Render(a.helpViewport.View() + "\n")
}

