420			outputPath = filepath.Join(outputDir, sanitizedName)
421		case targetType == TargetDirectory:
422			outputPath = filepath.Join(target, sanitizedName)
423		case targetType == TargetImage:
424			outputPath = sanitizedName
425		default:
426			return "", fmt.Errorf("unsupported target type: %s", targetType)
427		}
428	
429		var args []string
430	
431		switch targetType {
432		case TargetDirectory:
433			args = []string{"fs", "--format", "cyclonedx", "--output", outputPath}
434		case TargetImage:
435			args = []string{"image", "--format", "cyclonedx", "--output", outputPath}
436		}
437	
438		if server != "" {
439			args = append(args, "--server", server)
440		}
441	
442		var cmd *exec.Cmd
443	
444		if source == ToolSourceDocker {
445			dockerArgs := []string{"run", "--rm"}
446			if targetType == TargetDirectory {
447				if outputDir != "" {
448					dockerArgs = append(dockerArgs, "-v", target+":/scan:ro", "-v", outputDir+":/output")
449					args = []string{"fs", "--format", "cyclonedx", "--output", "/output/" + sanitizedName}
450				} else {
451					dockerArgs = append(dockerArgs, "-v", target+":/scan")
452					args = []string{"fs", "--format", "cyclonedx", "--output", "/scan/" + sanitizedName}
453				}
454				if server != "" {
455					args = append(args, "--server", server)
456				}
457				args = append(args, "/scan")
458			} else {
459				if server == "" {
460					dockerArgs = append(dockerArgs, "-v", "/var/run/docker.sock:/var/run/docker.sock:ro")
461				}
462				// Mount output directory
463				mountDir := outputDir
464				containerOutput := "/output/" + sanitizedName
465				if mountDir == "" {
466					mountDir = "."
467				}
468				dockerArgs = append(dockerArgs, "-v", mountDir+":/output")
469				args = []string{"image", "--format", "cyclonedx", "--output", containerOutput}
470				if server != "" {
471					args = append(args, "--server", server)
472				}
473				args = append(args, target)
474			}
475			dockerArgs = append(dockerArgs, image)
476			dockerArgs = append(dockerArgs, args...)
477			cmd = exec.CommandContext(ctx, "docker", dockerArgs...)
478		} else {
479			args = append(args, target)
480			cmd = exec.CommandContext(ctx, "trivy", args...)
481		}
482	
483		if err := cmd.Run(); err != nil {
484			if exitErr, ok := err.(*exec.ExitError); ok {
485				return "", fmt.Errorf("sbom generation failed: %s", string(exitErr.Stderr))
486			}
487			return "", fmt.Errorf("sbom generation failed: %w", err)
488		}
489	
490		return outputPath, nil
491	}
